-- ============================================================================
-- CARGA_PERSONAL_ALCALDIA.sql
-- Carga de 472 empleados del Listado del Personal de la Alcaldia.
-- Nombres/apellidos: del CNE cuando concuerda; del Excel cuando el CNE no tiene.
-- Sede (oficina_id): NO se asigna (queda null) — se asigna manualmente despues.
-- Excluye: 16 cedulas que no coinciden con el CNE y 21 filas sin cedula.
--
-- REQUISITO: correr antes SUPABASE_DEFINITIVO.sql (crea la columna telefono y
-- la RPC cargar_empleado_personal). Idempotente: si la cedula ya existe, solo
-- actualiza el telefono y rellena vacios (no pisa datos existentes).
-- ============================================================================

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname='cargar_empleado_personal') THEN
    RAISE EXCEPTION 'Falta la RPC cargar_empleado_personal. Corre primero SUPABASE_DEFINITIVO.sql';
  END IF;
END $$;


